var t=`0757-ugali`;var n=`world-0757`;var a=`KE`;var s=`eastern-africa`;var r=8;var o=40;var l={en:`Ugali`,ua:`Угалі`};var g={en:`Ugali is a Kenya classic prepared with cornmeal. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Угалі, страва кухні країни Кенія зі складниками: кукурудзяна крупа дрібного помелу. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var d=[{en:`Cook the listed ingredients in simmering water for about 9 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 9 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:9,i:[[`water`,1e3,`ml`],[`table-salt`,5,`g`]]},{en:`Pour cornmeal in a steady stream into boiling salted water, beat hard and cook until the ugali pulls away from the pot.`,ua:`Поступово всипайте кукурудзяне борошно в підсолений окріп, енергійно вимішуйте до моменту, коли угалі відставатиме від стінок каструлі.`,t:[`absorption-cooking`],m:20,i:[[`cornmeal`,380,`g`]]},{en:`Roll or press the prepared dough evenly into the desired thickness and shape.`,ua:`Розкачайте або розпластайте підготовлене тісто рівномірним шаром потрібної товщини та форми.`,t:[`pressing`,`rolling-out-dough`],m:8,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`unsalted-butter`,30,`g`]]}];var u={slug:t,id:n,country:`KE`,region:s,servings:8,minutes:40,title:l,text:g,steps:d};export{a as country,u as default,n as id,o as minutes,s as region,r as servings,t as slug,d as steps,g as text,l as title};